const request = $json;
const encodeHeader = (value) => '=?UTF-8?B?' + Buffer.from(value, 'utf8').toString('base64') + '?=';
const subject = request.subject;
const reference = request.rfc_message_id
  ? (request.rfc_message_id.startsWith('<') ? request.rfc_message_id : '<' + request.rfc_message_id + '>')
  : null;
const encodedBody = Buffer.from(request.body_text, 'utf8').toString('base64').match(/.{1,76}/g)?.join('\r\n') ?? '';
const headers = [
  'To: ' + request.recipient,
  'Subject: ' + encodeHeader(subject),
  'Message-ID: <mailflow-' + request.reply_id + '@mailflow.invalid>',
  'X-Mailflow-Idempotency-Key: ' + request.idempotency_key,
  'MIME-Version: 1.0',
  'Content-Type: text/plain; charset=UTF-8',
  'Content-Transfer-Encoding: base64'
];
if (reference) {
  headers.splice(2, 0, 'In-Reply-To: ' + reference, 'References: ' + reference);
}
const mime = headers.join('\r\n') + '\r\n\r\n' + encodedBody;
const raw = Buffer.from(mime, 'utf8').toString('base64')
  .replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/g, '');
return [{ json: { ...request, raw } }];

const request = $('Préparer message MIME').item.json;
const hasStatusCode = $json.statusCode !== undefined && $json.statusCode !== null;
const statusCode = hasStatusCode ? Number($json.statusCode) : null;
const isRecord = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);
let responseBody = {};
if (isRecord($json.body) && !('_readableState' in $json.body) && !('_outBuffer' in $json.body)) {
  responseBody = $json.body;
} else if (typeof $json.body === 'string') {
  try {
    const parsed = JSON.parse($json.body);
    if (isRecord(parsed)) responseBody = parsed;
  } catch {
    responseBody = {};
  }
} else if (typeof $json.id === 'string') {
  responseBody = $json;
}

const gmailMessageId = typeof responseBody.id === 'string' ? responseBody.id.trim() : '';
const responseThreadId = typeof responseBody.threadId === 'string' ? responseBody.threadId.trim() : '';
const gmailThreadId = responseThreadId || request.gmail_thread_id;
const successfulHttpStatus = !hasStatusCode || (statusCode >= 200 && statusCode < 300);
const confirmedSent = successfulHttpStatus &&
  gmailMessageId.length > 0 && gmailMessageId.length <= 255;

const base = {
  reply_id: request.reply_id,
  dispatch_id: request.dispatch_id,
  user_id: request.user_id,
  email_id: request.email_id,
  idempotency_key: request.idempotency_key
};

if (confirmedSent) {
  return [{ json: {
    ...base,
    callback_allowed: true,
    status: 'sent',
    gmail_message_id: gmailMessageId,
    gmail_thread_id: gmailThreadId
  } }];
}

if (hasStatusCode && statusCode >= 400 && statusCode < 500 && statusCode !== 408) {
  return [{ json: {
    ...base,
    callback_allowed: true,
    status: 'failed',
    error_message: 'Gmail API a refusé la requête (HTTP ' + statusCode + ').'
  } }];
}

return [{ json: {
  ...base,
  callback_allowed: false,
  status: 'ambiguous',
  error_message: 'Résultat Gmail ambigu. Aucun nouvel envoi ne doit être tenté automatiquement.'
} }];

return [{ json: {
  reply_id: $json.reply_id,
  dispatch_id: $json.dispatch_id,
  user_id: $json.user_id,
  email_id: $json.email_id,
  idempotency_key: $json.idempotency_key,
  status: 'failed',
  error_message: String($json.error_message || 'Payload d’envoi Gmail invalide.').slice(0, 2000)
} }];
